function getImageInfo(src) {
  return new Promise((resolve, reject) => {
    uni.getImageInfo({ src, success: resolve, fail: reject })
  })
}

function loadHtmlImage(src) {
  return new Promise((resolve, reject) => {
    const img = new Image()
    img.crossOrigin = 'anonymous'
    img.onload = () => resolve(img)
    img.onerror = reject
    img.src = src
  })
}

/** H5 使用原生 Canvas 合成，规避 uni canvasToTempFilePath 无水印/空白问题 */
async function applyWatermarkNativeH5(filePath) {
  const width = WATERMARK_CANVAS_W
  const height = WATERMARK_CANVAS_H
  const address = await resolveLocationAddress()
  const info = await getImageInfo(filePath).catch(() => ({ width: 0, height: 0 }))
  const img = await loadHtmlImage(filePath)
  const canvas = document.createElement('canvas')
  canvas.width = width
  canvas.height = height
  const ctx = canvas.getContext('2d')
  if (!ctx) throw new Error('canvas 2d unavailable')

  ctx.fillStyle = '#000000'
  ctx.fillRect(0, 0, width, height)
  let imageBottom = height
  if (info.width && info.height) {
    const scale = Math.min(width / info.width, height / info.height)
    const dw = info.width * scale
    const dh = info.height * scale
    const dx = (width - dw) / 2
    const dy = (height - dh) / 2
    imageBottom = dy + dh
    ctx.drawImage(img, dx, dy, dw, dh)
  } else {
    ctx.drawImage(img, 0, 0, width, height)
  }

  const lines = [`时间：${formatNow()}`, `位置：${address || '定位失败'}`]
  const fontSize = 30
  const lineHeight = fontSize * 1.45
  const padding = fontSize
  const bottomInset = fontSize * 0.6
  const coverVisibleBottom = Math.min(imageBottom, (height + width) / 2)

  ctx.shadowColor = 'rgba(0,0,0,0.75)'
  ctx.shadowBlur = 2
  ctx.shadowOffsetX = 0
  ctx.shadowOffsetY = 1
  ctx.fillStyle = '#b0b0b0'
  ctx.font = `bold ${fontSize}px sans-serif`
  ctx.textAlign = 'left'
  ctx.textBaseline = 'bottom'
  lines.forEach((line, i) => {
    ctx.fillText(
      line,
      padding,
      coverVisibleBottom - bottomInset - (lines.length - 1 - i) * lineHeight
    )
  })
  ctx.shadowColor = 'transparent'

  const blob = await new Promise((resolve, reject) => {
    canvas.toBlob(
      (b) => (b ? resolve(b) : reject(new Error('toBlob failed'))),
      'image/jpeg',
      0.9
    )
  })
  return { file: new File([blob], 'watermark.jpg', { type: 'image/jpeg' }) }
}

